function handleImageFile(event){const file=event.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file');return}const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{const scene=getScene(state.previewScene);if(!scene){URL.revokeObjectURL(url);return}const entry={id:makeSourceId(),type:'image',name:file.name,url,image,visible:true,x:.045,y:.06,width:.38,height:.38};scene.sources.push(entry);state.selectedSource=entry.id;updateStatus();toast('Image added as an overlay to Preview')};image.onerror=()=>{URL.revokeObjectURL(url);toast('This image could not be loaded')};image.src=url;event.target.value=''}
function addText(){openModal('Add text overlay','Add formatted text. Drag and resize the text box in Preview.',`<label class="field"><span>Text</span><input id="overlayText" maxlength="240" placeholder="Your text here"></label><label class="field"><span>Font</span><select id="overlayFont"><option value="system-ui">System Sans</option><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Impact">Impact</option><option value="monospace">Monospace</option></select></label><label class="field"><span>Text color</span><input id="overlayColor" type="color" value="#ffffff"></label><label class="field"><span>Size</span><select id="overlaySize"><option value="30">Small</option><option value="42" selected>Medium</option><option value="58">Large</option></select></label><label class="field"><span>Alignment</span><select id="overlayAlign"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label><div class="format-toggles"><label><input id="overlayBold" type="checkbox" checked> Bold</label><label><input id="overlayItalic" type="checkbox"> Italic</label></div>`,'Add text',()=>{const text=$('#overlayText').value.trim();if(!text){toast('Enter text for the overlay');return}const scene=getScene(state.previewScene),entry={id:makeSourceId(),type:'text',name:text.length>22?text.slice(0,20)+'…':text,text,color:$('#overlayColor').value,size:Number($('#overlaySize').value),fontFamily:$('#overlayFont').value,align:$('#overlayAlign').value,bold:$('#overlayBold').checked,italic:$('#overlayItalic').checked,backplate:true,backplateColor:'#101820',x:.05,y:.73,w:.72,h:.2,visible:true};scene.sources.push(entry);state.selectedTextId=entry.id;closeModal();updateStatus();toast('Text added—drag or resize it in Preview')})}
